mapper.select:
SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE c.chunk_id IN
#{chunkId}
AND doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND
AND doc.document_type IN
#{documentType}
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') OR c.embedding_text LIKE CONCAT('%', #{keyword}, '%') OR doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH query_terms(query_term) AS (
SELECT #{keyword}
), matched_terms AS ( SELECT search_term.chunk_id, COUNT(DISTINCT query_term.query_term) AS matched_term_count, SUM(search_term.weight + CASE WHEN search_term.term = query_term.query_term THEN 2 ELSE 0 END) AS term_score FROM query_terms query_term JOIN rag_chunk_search_terms search_term ON search_term.term = query_term.query_term OR search_term.term LIKE CONCAT(query_term.query_term, '%') JOIN rag_document_chunks c ON c.chunk_id = search_term.chunk_id JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND
AND doc.document_type IN
#{documentType}
GROUP BY search_term.chunk_id ORDER BY matched_term_count DESC, term_score DESC, search_term.chunk_id LIMIT #{limit} ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM matched_terms matched JOIN rag_document_chunks c ON c.chunk_id = matched.chunk_id JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND
AND doc.document_type IN
#{documentType}
ORDER BY matched.matched_term_count DESC, matched.term_score DESC, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END) + (CASE WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 2 ELSE 0 END)
) DESC, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH matched_docs AS ( SELECT doc.document_id, doc.document_type, doc.title, doc.source_org, doc.published_date, doc.source_url, doc.file_path FROM rag_documents doc WHERE doc.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.document_type, doc.title LIMIT #{limit} ), latest_versions AS ( SELECT c2.document_id, MAX(c2.chunk_version) AS chunk_version FROM rag_document_chunks c2 JOIN matched_docs md ON md.document_id = c2.document_id WHERE c2.use_yn = 'Y' GROUP BY c2.document_id ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM matched_docs doc JOIN latest_versions latest ON latest.document_id = doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id AND c.chunk_version = latest.chunk_version WHERE c.use_yn = 'Y' AND
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END) + (CASE WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 2 ELSE 0 END)
) DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH matched_docs AS ( SELECT doc.document_id, doc.document_type, doc.title, doc.source_org, doc.published_date, doc.source_url, doc.file_path, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) AS title_score FROM rag_documents doc WHERE doc.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY title_score DESC, doc.document_type, doc.title LIMIT 12 ), latest_versions AS ( SELECT c2.document_id, MAX(c2.chunk_version) AS chunk_version FROM rag_document_chunks c2 JOIN matched_docs md ON md.document_id = c2.document_id WHERE c2.use_yn = 'Y' GROUP BY c2.document_id ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM matched_docs doc JOIN latest_versions latest ON latest.document_id = doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id AND c.chunk_version = latest.chunk_version WHERE c.use_yn = 'Y' AND ORDER BY doc.title_score DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH matched_docs AS ( SELECT doc.document_id, doc.document_type, doc.title, doc.source_org, doc.published_date, doc.source_url, doc.file_path, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) AS title_score FROM rag_documents doc WHERE doc.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
) ORDER BY title_score DESC, doc.document_type, doc.title LIMIT 12 ), latest_versions AS ( SELECT c2.document_id, MAX(c2.chunk_version) AS chunk_version FROM rag_document_chunks c2 JOIN matched_docs md ON md.document_id = c2.document_id WHERE c2.use_yn = 'Y' GROUP BY c2.document_id ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM matched_docs doc JOIN latest_versions latest ON latest.document_id = doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id AND c.chunk_version = latest.chunk_version WHERE c.use_yn = 'Y' AND ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 6 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 4 ELSE 0 END) + (CASE WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.title_score DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND
AND doc.document_type IN
#{documentType}
AND (
c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY
(
CASE WHEN ( c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') ) THEN 1 ELSE 0 END
) DESC, GREATEST( 0,
CASE WHEN c.chunk_title = #{keyword} THEN 9 WHEN c.chunk_title LIKE CONCAT(#{keyword}, '%') THEN 8 WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 7 WHEN c.parent_section_title = #{keyword} THEN 6 WHEN c.parent_section_title LIKE CONCAT(#{keyword}, '%') THEN 5 WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 4 WHEN doc.title = #{keyword} THEN 3 WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 2 WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 1 ELSE 0 END
) DESC,
doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH chunk_matches AS ( SELECT c.chunk_id, c.document_id, c.sort_order,
CASE
WHEN (
LOWER(REGEXP_REPLACE(COALESCE(c.chunk_no, ''), '[^0-9A-Za-z가-힣]', '')) = LOWER(REGEXP_REPLACE(#{provisionTerm}, '[^0-9A-Za-z가-힣]', '')) OR LOWER(REGEXP_REPLACE(COALESCE(c.chunk_title, ''), '[^0-9A-Za-z가-힣]', '')) = LOWER(REGEXP_REPLACE(#{provisionTerm}, '[^0-9A-Za-z가-힣]', ''))
) THEN 0
WHEN (
LOWER(REGEXP_REPLACE(COALESCE(c.chunk_title, ''), '[^0-9A-Za-z가-힣]', '')) = LOWER(REGEXP_REPLACE(#{headingTerm}, '[^0-9A-Za-z가-힣]', '')) OR LOWER(REGEXP_REPLACE(COALESCE(c.parent_section_title, ''), '[^0-9A-Za-z가-힣]', '')) = LOWER(REGEXP_REPLACE(#{headingTerm}, '[^0-9A-Za-z가-힣]', ''))
) THEN 1
ELSE 2 END
2 AS match_class,
CASE WHEN c.chunk_text LIKE CONCAT('%', #{evidenceTerm}, '%') OR c.chunk_title LIKE CONCAT('%', #{evidenceTerm}, '%') OR c.parent_section_title LIKE CONCAT('%', #{evidenceTerm}, '%') THEN 1 ELSE 0 END
0 AS evidence_match_count FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND AND AND c.document_id IN
#{documentId}
), ranked_chunks AS ( SELECT matched.*, ROW_NUMBER() OVER ( PARTITION BY matched.document_id ORDER BY matched.match_class, matched.evidence_match_count DESC, matched.sort_order, matched.chunk_id ) AS document_rank FROM chunk_matches matched ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, CAST(NULL AS CHAR) AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType, c.quality_status AS qualityStatus, CAST(NULL AS CHAR) AS embeddingText, CAST(NULL AS CHAR) AS parentKey, c.chunk_version AS chunkVersion FROM ranked_chunks ranked JOIN rag_document_chunks c ON c.chunk_id = ranked.chunk_id JOIN rag_documents doc ON doc.document_id = ranked.document_id WHERE ranked.document_rank <= #{perDocumentLimit} ORDER BY ranked.match_class, ranked.document_id, ranked.sort_order, ranked.chunk_id LIMIT #{limit}
